#include <stdio.h>
#include <string.h>

unsigned int bkdr(const char *s) {
    unsigned int h = 0u;
    int c;
    while ((c = (unsigned char)*s++) != 0) {
        h = h * 31u + (unsigned int)c;
    }
    return h;
}

unsigned int djb2(const char *s) {
    unsigned int h = 5381u;
    int c;
    while ((c = (unsigned char)*s++) != 0) {
        h = ((h << 5) + h) + (unsigned int)c;
    }
    return h;
}

int main(void) {
    const char *ws[] = {"apple", "banana", "cat", "dog", "apple"};
    int n = (int)(sizeof(ws) / sizeof(ws[0]));
    int i;
    for (i = 0; i < n; i++) {
        unsigned int hb = bkdr(ws[i]);
        unsigned int hd = djb2(ws[i]);
        unsigned int modb = hb % 10007u;
        unsigned int modd = hd % 10007u;
        printf("'%s'  BKDR=%u mod10007=%u  DJB2=%u mod10007=%u\n", ws[i], hb, modb, hd, modd);
    }
    return 0;
}
